package com.tekwatt.reservation.service;import com.tekwatt.reservation.dto.*;import com.tekwatt.reservation.entity.*;import com.tekwatt.reservation.repository.ReservationRepository;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class ReservationService{private final ReservationRepository repo;public ReservationService(ReservationRepository r){repo=r;}public ReservationResponse create(ReservationRequest r){if(!r.expiresAt().isAfter(r.startsAt())||!r.expiresAt().isAfter(Instant.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid reservation time range");if(repo.existsByReference(r.reference()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Reference already exists");if(repo.hasConflict(r.connectorId(),r.startsAt(),r.expiresAt()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Connector is already reserved for this time");return ReservationResponse.from(repo.save(new Reservation(r.tenantId(),r.userId(),r.chargerId(),r.connectorId(),r.reference(),r.startsAt(),r.expiresAt())));}public ReservationResponse get(UUID id){Reservation r=find(id);r.expireIfNeeded();return ReservationResponse.from(r);}public List<ReservationResponse>list(UUID tenantId){return repo.findAllByTenantIdOrderByStartsAtDesc(tenantId).stream().peek(Reservation::expireIfNeeded).map(ReservationResponse::from).toList();}public ReservationResponse cancel(UUID id){return transition(id,ReservationStatus.CANCELLED);}public ReservationResponse complete(UUID id){return transition(id,ReservationStatus.COMPLETED);}private ReservationResponse transition(UUID id,ReservationStatus s){Reservation r=find(id);r.expireIfNeeded();if(r.getStatus()!=ReservationStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Reservation is not active");r.setStatus(s);return ReservationResponse.from(r);}private Reservation find(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reservation not found"));}}
